import { gsap } from 'gsap';
import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec2, color, positionLocal, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight } = THREE;

  const root = new Group();
  root.name = 'nav-dock';

  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // ---------------------------------------------------------------
  // palette / tokens
  // ---------------------------------------------------------------
  const palette = {
    railTop: '#1b1b23',
    railBottom: '#101015',
    paper: '#e8ecf2',
    inactive: '#a6adba',
    accent: '#ff2a38',
    surface: '#14141a',
  };

  const RAIL_W = 3.6;
  const RAIL_H = 0.5;
  const RAIL_D = 0.12;
  const ENTRY_STEP = 0.68;
  const HIT_W = 0.6;
  const HIT_H = 0.34;

  // ---------------------------------------------------------------
  // text content (bridging idiom)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'HOME', role: 'nav-active' },
    { text: 'FEATURES', role: 'nav-item' },
    { text: 'COLLECTION', role: 'nav-item' },
    { text: 'PRICING', role: 'nav-item' },
    { text: 'JOURNAL', role: 'nav-item' },
  ];

  const hubIds = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];

  // ---------------------------------------------------------------
  // inner group carries the visual rise-in mount motion
  // ---------------------------------------------------------------
  const inner = new Group();
  inner.position.y = 0.4;
  root.add(inner);

  // ---------------------------------------------------------------
  // machined rail — vertical albedo ramp, brushed metal PBR
  // ---------------------------------------------------------------
  const railGeo = new BoxGeometry(RAIL_W, RAIL_H, RAIL_D, 32, 4, 1);
  const railMat = new MeshPhysicalNodeMaterial();
  const railT = smoothstep(RAIL_H * 0.5, RAIL_H * -0.5, positionLocal.y);
  railMat.colorNode = mix(color(palette.railTop), color(palette.railBottom), railT);
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.3;
  if ('anisotropy' in railMat) {
    railMat.anisotropy = 0.6;
    railMat.anisotropyRotation = 0.0;
  }
  const rail = new Mesh(railGeo, railMat);
  rail.position.z = 0.15;
  inner.add(rail);
  disposables.push(railGeo, railMat);

  // chamfered edge highlight — thin bright strip along the top edge
  const edgeGeo = new BoxGeometry(RAIL_W - 0.04, 0.02, RAIL_D + 0.01);
  const edgeMat = new MeshPhysicalNodeMaterial();
  edgeMat.colorNode = color(palette.paper);
  edgeMat.roughness = 0.25;
  edgeMat.metalness = 0.6;
  edgeMat.clearcoat = 0.2;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, RAIL_H * 0.5 - 0.01, 0.15);
  inner.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // ---------------------------------------------------------------
  // contact shadow plane beneath the floating rail
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(RAIL_W * 1.25, RAIL_H * 1.8);
  const shadowMat = new MeshBasicNodeMaterial();
  const suv = uv().sub(vec2(0.5, 0.5));
  const falloff = smoothstep(0.5, 0.0, suv.length());
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = falloff.mul(0.35);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -RAIL_H * 0.5 - 0.06, 0.02);
  inner.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // local rim / accent light (scene already supplies ambient+key)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(palette.accent, 0.8);
  rim.position.set(-2, 1.5, 2);
  root.add(rim);

  // ---------------------------------------------------------------
  // nav entries
  // ---------------------------------------------------------------
  const total = items.length;
  const startX = -((total - 1) * ENTRY_STEP) / 2;
  let activeIndex = items.findIndex((it) => it.role === 'nav-active');
  if (activeIndex < 0) activeIndex = 0;

  const entries = [];

  function applyTextColor(textObj, hex) {
    textObj.traverse((child) => {
      if (child.material && child.material.color) {
        child.material.color.set(hex);
      }
    });
  }

  items.forEach((item, i) => {
    const xPos = startX + i * ENTRY_STEP;
    const cell = new Group();
    cell.position.x = xPos;

    const fontSize = item.typography?.fontSize ?? 13;
    const isActive = i === activeIndex;

    const text = ctx.fontAtlas.createText(String(item.text ?? '').toUpperCase(), {
      fontSize,
      color: isActive ? palette.paper : palette.inactive,
      align: 'center',
      letterSpacingPx: fontSize * 0.08,
    });
    text.position.set(0, 0.02, 0.22);
    cell.add(text);

    const hitGeo = new PlaneGeometry(HIT_W, HIT_H);
    const hitMat = new MeshBasicNodeMaterial();
    hitMat.colorNode = color('#000000');
    hitMat.opacityNode = null;
    hitMat.transparent = true;
    hitMat.opacity = 0.001;
    hitMat.depthWrite = false;
    const hitMesh = new Mesh(hitGeo, hitMat);
    hitMesh.position.z = 0.3;
    hitMesh.userData.navIndex = i;
    hitMesh.userData.hubId = hubIds[i] ?? null;
    cell.add(hitMesh);
    disposables.push(hitGeo, hitMat);

    inner.add(cell);
    entries.push({ group: cell, text, hit: hitMesh, xPos });
  });

  // ---------------------------------------------------------------
  // active underline bar
  // ---------------------------------------------------------------
  const underlineGeo = new BoxGeometry(0.28, 0.025, 0.02);
  const underlineMat = new MeshPhysicalNodeMaterial();
  underlineMat.colorNode = color(palette.accent);
  underlineMat.emissiveNode = color(palette.accent).mul(1.8);
  underlineMat.roughness = 0.4;
  underlineMat.metalness = 0.1;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(entries[activeIndex]?.xPos ?? 0, -0.04, 0.28);
  inner.add(underline);
  disposables.push(underlineGeo, underlineMat);

  // ---------------------------------------------------------------
  // mount motion — rise-in
  // ---------------------------------------------------------------
  const mountTl = gsap.timeline();
  mountTl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  timelines.push(mountTl);

  // ---------------------------------------------------------------
  // interaction helpers
  // ---------------------------------------------------------------
  function resolveHit(e) {
    const obj = e?.object ?? e?.intersection?.object ?? e?.target ?? null;
    if (!obj || typeof obj.userData?.navIndex !== 'number') return null;
    return entries[obj.userData.navIndex] ?? null;
  }

  function onPointerOver(e) {
    const entry = resolveHit(e);
    if (!entry || entry === entries[activeIndex]) return;
    const tl = gsap.to({}, {
      duration: 0.16,
      ease: 'power1.out',
      onUpdate() {
        // simple direct color set (msdf color has no smooth uniform lerp guarantee)
      },
    });
    applyTextColor(entry.text, palette.paper);
    timelines.push(tl);
  }

  function onPointerOut(e) {
    const entry = resolveHit(e);
    if (!entry || entry === entries[activeIndex]) return;
    applyTextColor(entry.text, palette.inactive);
  }

  function onPointerDown(e) {
    const entry = resolveHit(e);
    if (!entry) return;
    const tl = gsap.to(entry.group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(4)',
    });
    const tl2 = gsap.to(entry.group.position, {
      z: -0.03,
      duration: 0.12,
      ease: 'back.out(4)',
    });
    timelines.push(tl, tl2);
  }

  function onPointerUp(e) {
    const entry = resolveHit(e);
    if (!entry) return;
    const tl = gsap.to(entry.group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'power2.out',
    });
    const tl2 = gsap.to(entry.group.position, {
      z: 0,
      duration: 0.12,
      ease: 'power2.out',
    });
    timelines.push(tl, tl2);
  }

  function onClick(e) {
    const obj = e?.object ?? e?.intersection?.object ?? e?.target ?? null;
    if (!obj || typeof obj.userData?.navIndex !== 'number') return;
    const newIndex = obj.userData.navIndex;
    if (newIndex === activeIndex) return;

    const prevEntry = entries[activeIndex];
    const nextEntry = entries[newIndex];
    if (prevEntry) applyTextColor(prevEntry.text, palette.inactive);
    if (nextEntry) applyTextColor(nextEntry.text, palette.paper);

    activeIndex = newIndex;

    const tl = gsap.to(underline.position, {
      x: nextEntry.xPos,
      duration: 0.26,
      ease: 'back.out(1.7)',
    });
    timelines.push(tl);

    const hubId = obj.userData.hubId;
    if (hubId) {
      ctx.emit('navigate', { to: hubId });
    }
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
  };

  // ---------------------------------------------------------------
  // cinematic primitives (config declares none — loop is generic)
  // ---------------------------------------------------------------
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives?.[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') handle.cleanup();
    }
    for (const res of disposables) {
      if (res && typeof res.dispose === 'function') res.dispose();
    }
    root.traverse((child) => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        for (const m of mats) {
          if (m && typeof m.dispose === 'function') m.dispose();
        }
      }
    });
  };

  return root;
}
